import React, { useState } from 'react';
import { FaFilter, FaChevronDown, FaChevronUp } from 'react-icons/fa';
import { colors } from '../../styles/theme';

function FiltresAvances({ 
  titre = "Filtres", 
  enfants, 
  collapsible = false, 
  defaultOpen = true 
}) {
  const [isOpen, setIsOpen] = useState(defaultOpen);

  return (
    <div 
      className="rounded-lg shadow-md mb-6 transition-all duration-300"
      style={{ 
        backgroundColor: colors.globalLight,
        borderLeft: `4px solid ${colors.secondaryColor}`,
        padding: '20px'
      }}
    >
      <div 
        className={`flex items-center ${collapsible ? 'cursor-pointer' : ''} mb-3`}
        onClick={collapsible ? () => setIsOpen(!isOpen) : undefined}
      >
        <FaFilter 
          className="mr-2" 
          style={{ color: colors.secondaryColor }}
        />
        <h2 
          className="text-lg font-semibold flex-grow"
          style={{ color: colors.complementaryColor }}
        >
          {titre}
        </h2>
        {collapsible && (
          isOpen ? 
            <FaChevronUp style={{ color: colors.textLight }} /> : 
            <FaChevronDown style={{ color: colors.textLight }} />
        )}
      </div>

      {(!collapsible || isOpen) && (
        <div 
          className="transition-all duration-300"
          style={{ 
            maxHeight: isOpen ? '1000px' : '0',
            overflow: 'hidden',
            opacity: isOpen ? 1 : 0
          }}
        >
          <div className="pt-2">
            {enfants}
          </div>
        </div>
      )}
    </div>
  );
}

export default FiltresAvances;
